import {insightFor} from './diagnostic-insights.js';
import {bindAlternatingWhatsapp,icon} from './site.js';
import {questionsFor,buildResult,toggleSelection,sanitizeAnswers,resultText} from './diagnostic-engine.js';
const key='speed-nexus-diagnostic-v2', wizard=document.getElementById('wizard'), stages=document.getElementById('stages');
let answers={},index=0,finished=false,saved=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const raw=JSON.parse(sessionStorage.getItem(key));if(raw?.version===2&&raw.answers&&typeof raw.answers==='object'){const clean=sanitizeAnswers(raw.answers);if(Object.keys(clean).length)saved={answers:clean,id:raw.id,finished:raw.finished===true};}}catch{}
function persist(){try{sessionStorage.setItem(key,JSON.stringify({version:2,answers:sanitizeAnswers(answers),id:questionsFor(answers)[index]?.id,finished}));}catch{}}
function stageIndex(q){if(q?.group==='Contexto')return 0;if(['Visão geral','Rotina e informação'].includes(q?.group))return 1;if(q?.group==='Próximo passo')return 3;return 2;}
function renderStages(active){stages.innerHTML=['Contexto','Visão geral','Aprofundamento','Próximo passo'].map((s,i)=>`<div class="stage ${i===active?'active':''}" ${i===active?'aria-current="step"':''}><span class="stage-dot">${i<active?'✓':i+1}</span><span>${s}</span></div>`).join('');}
function focusTitle(){requestAnimationFrame(()=>{const title=wizard.querySelector('[data-focus]');title?.focus({preventScroll:true});if(window.scrollY>wizard.offsetTop-90)wizard.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});}
function isAnswered(q){return q.multi?Array.isArray(answers[q.id])&&answers[q.id].length>0:typeof answers[q.id]==='string'&&answers[q.id].length>0;}
function insightMarkup(question){
 const insight=insightFor(question,answers);
 return insight?`<aside class="diagnostic-insight" aria-label="Insight da Speed Nexus"><div class="insight-label">Insight <span>Speed Nexus · ${esc(insight.section)}</span></div><p>${esc(insight.text)}</p><small>${esc(insight.approach)}</small></aside>`:"";
}
function renderQuestion(focus=false){
 const qs=questionsFor(answers);index=Math.max(0,Math.min(index,qs.length-1));const q=qs[index];renderStages(stageIndex(q));
 wizard.innerHTML=`<div class="wizard-top"><span>DIAGNÓSTICO GRATUITO</span><span id="step-count" aria-live="polite">Pergunta ${index+1} de ${qs.length}</span></div><div class="progress" role="progressbar" aria-label="Progresso do questionário" aria-valuemin="0" aria-valuemax="${qs.length}" aria-valuenow="${index}"><span style="width:${index/qs.length*100}%"></span></div><form id="question-form" novalidate><div class="question-panel"><p class="question-group">${esc(q.group)}</p><h2 id="q-title" data-focus tabindex="-1">${esc(q.title)}</h2><p class="question-help" id="q-help">${esc(q.help)}</p><p class="select-note">${q.multi?'Selecione uma ou mais opções.':'Selecione uma opção.'}${q.id==='areas'?' O número de perguntas se ajusta à sua escolha.':''}</p><fieldset class="choices" aria-labelledby="q-title" aria-describedby="q-help"><legend class="sr-only">${esc(q.title)}</legend>${q.options.map(option=>`<label class="choice"><input type="${q.multi?'checkbox':'radio'}" name="${q.id}" value="${esc(option.id)}" ${q.multi?answers[q.id]?.includes(option.id)?'checked':'':answers[q.id]===option.id?'checked':''}><span>${esc(option.label)}</span></label>`).join('')}</fieldset>${insightMarkup(q)}<p class="error" id="answer-error" role="alert" hidden>Selecione ${q.multi?'pelo menos uma opção':'uma opção'} para continuar.</p></div><div class="question-nav"><button class="btn" id="back" type="button" ${index===0?'disabled':''}>${icon('back')} Voltar</button><button class="btn primary" type="submit" id="next">${index===qs.length-1?'Ver minha leitura inicial':'Continuar'} ${icon('next')}</button></div></form>`;
 wizard.querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{
  if(q.multi){answers[q.id]=toggleSelection(answers[q.id]??[],input.value);wizard.querySelectorAll('input').forEach(el=>el.checked=answers[q.id].includes(el.value));}else answers[q.id]=input.value;
  answers=sanitizeAnswers(answers);const len=questionsFor(answers).length;
  wizard.querySelector('#step-count').textContent=`Pergunta ${index+1} de ${len}`;
  const progress=wizard.querySelector('[role=progressbar]');progress.setAttribute('aria-valuemax',String(len));progress.querySelector('span').style.width=`${index/len*100}%`;
  wizard.querySelector('#answer-error').hidden=true;persist();
 }));
 wizard.querySelector('#back').addEventListener('click',()=>{index--;persist();renderQuestion(true);});
 wizard.querySelector('#question-form').addEventListener('submit',e=>{e.preventDefault();if(!isAnswered(q)){wizard.querySelector('#answer-error').hidden=false;wizard.querySelector('input')?.focus();return;}const current=questionsFor(answers);if(index>=current.length-1){finished=true;persist();renderResult(true);}else{index++;persist();renderQuestion(true);}});
 if(focus)focusTitle();
}
function clearAndStart(){answers={};index=0;finished=false;try{sessionStorage.removeItem(key);}catch{}renderQuestion(true);}
function download(){const blob=new Blob([resultText(answers)],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Speed-Nexus-leitura-inicial.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderResult(focus=false){
 const r=buildResult(answers);renderStages(3);
 const levels={1:'Investigar',2:'Atenção pela recorrência relatada',3:'Verificar com prioridade'};
 wizard.innerHTML=`<div class="result-intro"><p class="question-group">SUA LEITURA INICIAL</p><h2 data-focus tabindex="-1">Um ponto de partida<br>para entender melhor.</h2><p>Esta leitura organiza o que você relatou. Ela não confirma causas nem avalia toda a saúde da empresa. As prioridades abaixo são preliminares e precisam ser verificadas com você e a equipe.</p><div class="coverage"><strong>Aprofundamento:</strong> ${esc(r.coverage.join(', ')||'Nenhuma área específica selecionada. A leitura considera as perguntas gerais.')}<br>As demais áreas não foram investigadas em detalhe.</div></div><div class="result-body"><h3 class="result-section-title">Sinais e pontos para investigar</h3><p class="result-note">${r.signals.length?'Primeiro aparecem relatos de comprometimento de caixa, dados ou continuidade. Depois, dificuldades recorrentes com impacto. Os demais sinais precisam de investigação. Itens no mesmo grupo não têm uma ordem definitiva. As possíveis soluções indicam caminhos gerais; a análise aprofundada verifica qual faz sentido e define os detalhes.':'As respostas não trouxeram sinais suficientes para apontar um problema específico. Isso não confirma que tudo esteja bem. A conversa e a verificação da rotina podem trazer informações que este questionário não capturou.'}</p>${r.signals.map(s=>`<article class="finding"><div class="finding-top"><span>${esc(s.area)}</span><span class="badge ${s.level===3?'urgent':''}">${levels[s.level]}</span></div><h3>${esc(s.title)}</h3><p><strong>O que você relatou:</strong> ${esc(s.evidence)}.</p><p><strong>O que investigar:</strong> ${esc(s.investigate)}</p><p><strong>Possível solução:</strong> ${esc(s.solution)}</p><p><strong>Próximo passo:</strong> ${esc(s.next)}</p></article>`).join('')}
 ${r.gaps.length?`<section class="result-section"><h3 class="result-section-title">Informações que ainda faltam</h3><p class="result-note">Você marcou que não sabe avaliar estes pontos. Eles precisam ser esclarecidos; não foram tratados como sinal de maior gravidade.</p><ul>${r.gaps.map(g=>`<li><strong>${esc(g.context)}:</strong> ${esc(g.title)}</li>`).join('')}</ul></section>`:''}
 ${r.strengths.length?`<section class="result-section"><h3 class="result-section-title">O que você relatou como organizado</h3><ul>${r.strengths.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></section>`:''}
 <section class="result-section"><h3 class="result-section-title">Seu contexto para o próximo passo</h3><p class="result-note"><strong>O que você busca:</strong> ${esc(r.goal)}.<br><strong>Quando quer conversar:</strong> ${esc(r.timing)}.<br>Seu momento para contratar não altera a leitura dos problemas.</p></section>
 <section class="next-step"><p class="question-group">DO SINAL À INVESTIGAÇÃO</p><h3>Quer entender as causas?</h3><p>O diagnóstico aprofundado é uma etapa paga e personalizada. Partimos dessas respostas, conversamos com você e com quem executa as rotinas e analisamos os processos e registros acordados. Você recebe um mapa de problemas, prioridades e a definição detalhada das soluções dentro do alcance contratado.</p><p>Antes de contratar, combinamos preço, prazo, alcance e entregáveis. Implementações e especialistas são definidos em uma proposta própria. Não há contratação automática.</p><div class="actions"><a id="send-whatsapp" class="btn primary" target="_blank" rel="noopener noreferrer" href="#">Conversar sobre meu diagnóstico ${icon('chat')}</a></div><small class="micro">Ao clicar, você abre o WhatsApp com um resumo desta leitura. Confira a mensagem e envie apenas se quiser. Para compartilhar todas as respostas, baixe o resultado e anexe o arquivo na conversa. Nada foi enviado automaticamente.</small><p class="result-note">Se preferir, fale diretamente: <a href="https://wa.me/5543984457932" target="_blank" rel="noopener noreferrer">(43) 98445-7932</a> ou <a href="https://wa.me/5543984740935" target="_blank" rel="noopener noreferrer">(43) 98474-0935</a>.</p></section>
 <div class="result-actions"><button type="button" class="btn" id="download">Baixar resultado completo</button><button type="button" class="btn" id="print">Imprimir / salvar PDF</button><button type="button" class="btn" id="review">Revisar respostas</button><button type="button" class="btn" id="restart">Recomeçar</button></div><div id="restart-confirm" class="result-section" hidden><p class="result-note">Apagar as respostas desta aba e começar um novo diagnóstico?</p><div class="actions"><button class="btn primary" id="confirm-restart" type="button">Sim, recomeçar</button><button class="btn" id="cancel-restart" type="button">Manter resultado</button></div></div></div>`;
 const send=wizard.querySelector('#send-whatsapp');
 // Keep the messaging URL bounded; a complete local report is available as a download.
 const summary=r.signals.slice(0,5).map(s=>s.area+': '+s.title+' — Possibilidade: '+s.solution).join('\n')||'Sem sinais suficientes para apontar problema específico.';
 const handoff='Olá! Fiz o diagnóstico gratuito da Speed Nexus e quero conversar sobre uma análise aprofundada.\n\nÁreas aprofundadas: '+(r.coverage.join(', ')||'Somente visão geral')+'\nObjetivo: '+r.goal+'\nMomento: '+r.timing+'\n\nLEITURA PRELIMINAR\n'+summary+'\n\nInformações a esclarecer: '+r.gaps.length+'. Causas e prioridades ainda precisam ser verificadas. Tenho a opção de baixar e compartilhar o relatório completo com as respostas.';
 bindAlternatingWhatsapp(send,handoff);
 wizard.querySelector('#download').addEventListener('click',download);wizard.querySelector('#print').addEventListener('click',()=>window.print());
 wizard.querySelector('#review').addEventListener('click',()=>{finished=false;index=0;persist();renderQuestion(true);});
 wizard.querySelector('#restart').addEventListener('click',()=>{wizard.querySelector('#restart-confirm').hidden=false;wizard.querySelector('#confirm-restart').focus();});
 wizard.querySelector('#confirm-restart').addEventListener('click',clearAndStart);wizard.querySelector('#cancel-restart').addEventListener('click',()=>{wizard.querySelector('#restart-confirm').hidden=true;wizard.querySelector('#restart').focus();});
 if(focus)focusTitle();
}
if(saved){renderStages(0);wizard.innerHTML=`<div class="resume-panel"><p class="question-group">SEU PERCURSO</p><h2 data-focus tabindex="-1">Vamos continuar?</h2><p>Encontramos respostas salvas nesta aba. Você pode retomar de onde parou ou começar outra leitura.</p><div class="actions"><button type="button" id="resume" class="btn primary">${saved.finished?'Ver meu resultado':'Continuar diagnóstico'} ${icon('next')}</button><button type="button" id="new" class="btn">Começar de novo</button></div><small class="micro">As respostas não foram enviadas à Speed Nexus.</small></div>`;wizard.querySelector('#resume').addEventListener('click',()=>{answers=saved.answers;const qs=questionsFor(answers);const missing=qs.findIndex(q=>!isAnswered(q));finished=saved.finished&&missing===-1;index=Math.max(0,qs.findIndex(q=>q.id===saved.id));if(finished)renderResult(true);else{if(missing!==-1)index=Math.min(index,missing);renderQuestion(true);}});wizard.querySelector('#new').addEventListener('click',clearAndStart);}else renderQuestion();
